// Prepare context for Claude AI analysis
const labData = $('When Called by Another Workflow').first().json;
const referenceRanges = $input.all();

// Build reference ranges lookup
const rangesLookup = {};
referenceRanges.forEach(row => {
  const data = row.json;
  rangesLookup[data.Test_Name] = {
    normalMin: parseFloat(data.Normal_Min) || null,
    normalMax: parseFloat(data.Normal_Max) || null,
    criticalLow: parseFloat(data.Critical_Low) || null,
    criticalHigh: parseFloat(data.Critical_High) || null,
    units: data.Units || '',
    notes: data.Notes || ''
  };
});

// Analyze each test result
const analysisResults = [];
let hasCritical = false;
let hasAbnormal = false;

labData.tests.forEach(test => {
  const testName = test.testName;
  const value = test.value;
  const range = rangesLookup[testName];

  let status = 'UNKNOWN';
  let interpretation = '';

  if (range) {
    // Check for critical values
    if (range.criticalLow !== null && value < range.criticalLow) {
      status = 'CRITICAL_LOW';
      interpretation = `CRITICAL: ${testName} is critically low (${value} ${range.units}, critical threshold <${range.criticalLow})`;
      hasCritical = true;
    } else if (range.criticalHigh !== null && value > range.criticalHigh) {
      status = 'CRITICAL_HIGH';
      interpretation = `CRITICAL: ${testName} is critically high (${value} ${range.units}, critical threshold >${range.criticalHigh})`;
      hasCritical = true;
    }
    // Check for abnormal (out of normal range but not critical)
    else if (range.normalMin !== null && value < range.normalMin) {
      status = 'ABNORMAL_LOW';
      interpretation = `${testName} is below normal range (${value} ${range.units}, normal ${range.normalMin}-${range.normalMax})`;
      hasAbnormal = true;
    } else if (range.normalMax !== null && value > range.normalMax) {
      status = 'ABNORMAL_HIGH';
      interpretation = `${testName} is above normal range (${value} ${range.units}, normal ${range.normalMin}-${range.normalMax})`;
      hasAbnormal = true;
    }
    // Normal range
    else {
      status = 'NORMAL';
      interpretation = `${testName} is within normal range (${value} ${range.units}, normal ${range.normalMin}-${range.normalMax})`;
    }
  } else {
    // No reference range available
    status = 'UNKNOWN';
    interpretation = `${testName}: ${value} (no reference range available)`;
  }

  analysisResults.push({
    testName: testName,
    value: value,
    status: status,
    interpretation: interpretation,
    referenceRange: range
  });
});

// Build summary for AI
const criticalTests = analysisResults.filter(t => t.status.startsWith('CRITICAL'));
const abnormalTests = analysisResults.filter(t => t.status.startsWith('ABNORMAL'));
const normalTests = analysisResults.filter(t => t.status === 'NORMAL');

const summary = {
  totalTests: analysisResults.length,
  normalCount: normalTests.length,
  abnormalCount: abnormalTests.length,
  criticalCount: criticalTests.length,
  hasCritical: hasCritical,
  hasAbnormal: hasAbnormal,
  isAllNormal: !hasCritical && !hasAbnormal && analysisResults.length > 0
};

return {
  json: {
    patient: labData.patient,
    labOrder: labData.labOrder,
    tests: labData.tests,

    // Analysis results
    analysisResults: analysisResults,
    criticalTests: criticalTests,
    abnormalTests: abnormalTests,
    normalTests: normalTests,
    summary: summary,

    // Pass through for AI
    metadata: labData.metadata
  }
};

// Build comprehensive prompt for Claude AI
const data = $input.first().json;

const patient = data.patient;
const labOrder = data.labOrder;
const summary = data.summary;
const criticalTests = data.criticalTests;
const abnormalTests = data.abnormalTests;
const normalTests = data.normalTests;

// Build system prompt with clinical protocols
const systemPrompt = `You are a medical lab result triage assistant for Dr. Jennifer's practice.

Your role is to analyze lab results and categorize them for appropriate notification:

CLINICAL PROTOCOLS:

✅ NORMAL (70% of cases):
- ALL test values within normal range
- No critical values
- No concerning patterns or combinations
- Patient can be notified automatically

⚠️ ABNORMAL (20% of cases):
- ONE or more values outside normal range (but not critical)
- Concerning combinations (e.g., high cholesterol + high LDL)
- Requires doctor review before patient notification
- Doctor may want to order follow-up tests or schedule appointment

🚨 CRITICAL (10% of cases):
- ONE or more values in critical range (life-threatening)
- Immediate doctor intervention required
- Examples: Glucose <50 or >400, Hemoglobin <7, Potassium >6.0, eGFR <15
- DO NOT auto-notify patient - doctor/staff must call immediately

RETURN FORMAT:
Respond with ONLY valid JSON (no markdown, no explanations outside JSON):
{
  "decision": "NORMAL" | "ABNORMAL" | "CRITICAL",
  "reasoning": "Brief clinical reasoning (2-3 sentences)",
  "concerningFindings": ["array of specific abnormal/critical values"],
  "recommendedAction": "What should happen next",
  "patientMessage": "Suggested message for patient (if NORMAL or ABNORMAL)",
  "urgencyLevel": "routine" | "soon" | "urgent" | "immediate"
}`;

// Build user prompt with lab results
const criticalList = criticalTests.map(t => t.interpretation).join('\n');
const abnormalList = abnormalTests.map(t => t.interpretation).join('\n');
const normalList = normalTests.map(t => t.interpretation).join('\n');

const userPrompt = `PATIENT CONTEXT:
Name: ${patient.name}
Age/DOB: ${patient.dateOfBirth || 'Unknown'}
Gender: ${patient.gender || 'Unknown'}
Primary Doctor: ${patient.primaryDoctor}
Last Visit: ${patient.lastVisitDate || 'Unknown'}

LAB ORDER:
Collection Date: ${labOrder.collectionDate || 'Unknown'}
Ordering Provider: ${labOrder.orderingProvider}
Lab Company: ${labOrder.labCompany}

TEST RESULTS SUMMARY:
Total Tests: ${summary.totalTests}
Normal: ${summary.normalCount}
Abnormal: ${summary.abnormalCount}
Critical: ${summary.criticalCount}

${summary.criticalCount > 0 ? `🚨 CRITICAL VALUES (${summary.criticalCount}):
${criticalList}
` : ''}
${summary.abnormalCount > 0 ? `⚠️ ABNORMAL VALUES (${summary.abnormalCount}):
${abnormalList}
` : ''}
${summary.normalCount > 0 ? `✅ NORMAL VALUES (${summary.normalCount}):
${normalList}
` : ''}

QUESTION: Based on the clinical protocols, should these lab results be categorized as NORMAL (auto-notify patient), ABNORMAL (doctor review required), or CRITICAL (immediate intervention)?`;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,

    // Pass through for next nodes
    patientData: data
  }
};

// Parse Claude's JSON response and validate
const aiResponse = $input.first().json;
const promptData = $('Build AI Prompt').first().json;

let decision = null;
let parseError = false;

// Try to extract JSON from AI response
try {
  let responseText = '';

  // Handle different response formats
  if (typeof aiResponse === 'string') {
    responseText = aiResponse;
  } else if (aiResponse.response) {
    responseText = aiResponse.response;
  } else if (aiResponse.text) {
    responseText = aiResponse.text;
  } else if (aiResponse.output) {
    responseText = aiResponse.output;
  } else if (aiResponse.decision) {
    decision = aiResponse;
  } else {
    responseText = JSON.stringify(aiResponse);
  }

  if (!decision && responseText) {
    // Remove markdown code blocks if present
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    decision = JSON.parse(responseText);
  }

  // Validate decision structure
  if (!decision.decision || !['NORMAL', 'ABNORMAL', 'CRITICAL'].includes(decision.decision)) {
    throw new Error('Invalid decision value');
  }

} catch (error) {
  console.error('Failed to parse AI response:', error.message);
  parseError = true;

  // Safety fallback: If critical tests detected, escalate
  const patientData = promptData.patientData;
  if (patientData.summary.hasCritical) {
    decision = {
      decision: 'CRITICAL',
      reasoning: `Parse error occurred, but critical values detected. Escalating for safety.`,
      concerningFindings: patientData.criticalTests.map(t => t.interpretation),
      recommendedAction: 'Immediate doctor review required due to critical lab values',
      urgencyLevel: 'immediate'
    };
  } else if (patientData.summary.hasAbnormal) {
    decision = {
      decision: 'ABNORMAL',
      reasoning: `Parse error occurred, but abnormal values detected. Escalating for safety.`,
      concerningFindings: patientData.abnormalTests.map(t => t.interpretation),
      recommendedAction: 'Doctor review required',
      urgencyLevel: 'soon'
    };
  } else {
    decision = {
      decision: 'NORMAL',
      reasoning: 'All values appear normal',
      concerningFindings: [],
      recommendedAction: 'Notify patient of normal results',
      patientMessage: 'Your lab results are normal.',
      urgencyLevel: 'routine'
    };
  }
}

// Add metadata
const output = {
  // AI decision
  decision: decision.decision,
  reasoning: decision.reasoning || 'No reasoning provided',
  concerningFindings: decision.concerningFindings || [],
  recommendedAction: decision.recommendedAction || '',
  patientMessage: decision.patientMessage || '',
  urgencyLevel: decision.urgencyLevel || 'routine',

  // Metadata
  parseError: parseError,
  timestamp: new Date().toISOString(),
  aiModel: 'claude-3-5-sonnet-20241022',

  // Original context (for notification workflow)
  patientData: promptData.patientData,

  // For audit log
  systemPrompt: promptData.systemPrompt,
  userPrompt: promptData.userPrompt,
  rawAIResponse: aiResponse
};

return { json: output };
